def strategy(history, rng):
    if not history:
        return 'C'
    n = len(history)
    if n >= 99:
        return 'D'
    last_my, last_opp = history[-1]
    if n < 8:
        return 'C' if last_opp == 'C' else 'D'
    opp_c = sum(1 for a, b in history if b == 'C')
    my_c = sum(1 for a, b in history if a == 'C')
    recent = history[-12:]
    opp_recent_c = sum(1 for a, b in recent if b == 'C')
    tol = 0
    pun = 0
    start = max(1, n - 12)
    for i in range(start, n):
        if history[i - 1][0] == 'D':
            if history[i][1] == 'C':
                tol += 1
            else:
                pun += 1
    if last_opp == 'C' and tol > pun and tol >= 1 and opp_c >= n - 2 and n >= 30:
        return 'D'
    if last_opp == 'C' and last_my == 'C' and opp_c >= n - 1 and n >= 70 and n < 90:
        if rng.random() < 0.02:
            return 'D'
    if opp_c >= 95:
        return 'C'
    if opp_c <= 3 and n >= 20:
        return 'D'
    if opp_recent_c == 0:
        if rng.random() < 0.03:
            return 'C'
        return 'D'
    if opp_recent_c >= 11:
        return 'C'
    perceived = opp_c / n
    if perceived > 0.65:
        if last_opp == 'D':
            if last_my == 'C':
                return 'D'
            if opp_recent_c >= 10:
                return 'C'
            if rng.random() < 0.08:
                return 'C'
            return 'D'
        return 'C'
    if my_c / n > 0.75 and last_opp == 'D':
        return 'D'
    if n > 60 and opp_c > 35 and my_c < 30:
        return 'C'
    if last_opp == 'D':
        if rng.random() < 0.15 + 0.25 * (opp_recent_c / 12):
            return 'C'
        return 'D'
    if n % 10 == 9 and my_c > opp_c + 10:
        return 'D'
    return 'C'
